<script setup>
import { computed, reactive, ref } from 'vue';
import Icon from '../components/Icon.vue'; import Modal from '../components/Modal.vue';
import { data, canEdit, saveRecord, notify, presence } from '../store.js';
import { idEqual } from '../domain.js';
const query = ref(''), editing = ref(false), form = reactive({}), saving = ref(false), error = ref('');
const rows = computed(() => data.rooms.filter(r => `${r.name} ${r.number} ${r.purpose}`.toLowerCase().includes(query.value.toLowerCase())));
function edit(room) { Object.keys(form).forEach(k => delete form[k]); Object.assign(form, room || { name: '', number: '', floor: 1, purpose: '', equipment: '', capacity: 10, zone: 'Общая зона' }); error.value = ''; editing.value = true; }
async function submit() {
  saving.value = true; error.value = '';
  try {
    if (data.rooms.some(r => !idEqual(r.id, form.id) && String(r.floor) === String(form.floor) && r.number === form.number.trim())) throw new Error('На этом этаже уже есть помещение с таким номером.');
    await saveRecord('rooms', { ...form, name: form.name.trim(), number: form.number.trim() }); editing.value = false; notify('Помещение сохранено.');
  } catch (e) { error.value = e.message; } finally { saving.value = false; }
}
</script>
<template><div class="page-header"><div><span class="eyebrow">ПРОСТРАНСТВО ОРГАНИЗАЦИИ</span><h1>Помещения<span class="heading-dot">.</span></h1><p>Расположение, назначение и оборудование контроля доступа.</p></div><button v-if="canEdit" class="button primary" @click="edit()"><Icon name="plus" :size="18" />Добавить помещение</button></div><div class="toolbar"><label class="search-field"><Icon name="search" :size="17" /><input v-model="query" placeholder="Название, номер или назначение…" aria-label="Поиск помещения" /></label><span class="toolbar-count">{{ rows.length }} помещений</span></div><section class="panel"><div v-if="!rows.length" class="empty-state"><Icon name="rooms" :size="36" /><h3>Помещения не найдены</h3><p>Добавьте помещение или измените поиск.</p></div><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>Помещение</th><th>Расположение</th><th>Зона доступа</th><th>Оборудование</th><th>Вместимость</th><th v-if="canEdit"></th></tr></thead><tbody><tr v-for="room in rows" :key="room.id"><td><div class="person-cell"><span class="room-symbol"><Icon name="rooms" :size="20" /></span><div><strong>{{ room.name }}</strong><small>{{ room.purpose }}</small></div></div></td><td>{{ room.floor }} этаж · {{ room.number }}</td><td><span class="badge" :class="room.zone === 'Ограниченный доступ' ? 'amber' : 'neutral'">{{ room.zone }}</span></td><td class="equipment-cell">{{ room.equipment || 'Не указано' }}</td><td><strong>{{ [...presence.values()].filter(p => idEqual(p.roomId, room.id)).length }}</strong><span class="muted"> / {{ room.capacity }} чел.</span></td><td v-if="canEdit"><button class="icon-button" :aria-label="`Изменить: ${room.name}`" @click="edit(room)"><Icon name="edit" :size="17" /></button></td></tr></tbody></table></div></section><Modal v-if="editing" :title="form.id ? 'Редактировать помещение' : 'Новое помещение'" @close="!saving && (editing = false)"><form id="room-form" class="form-grid" @submit.prevent="submit"><label class="span-2">Название<input v-model="form.name" required maxlength="100" /></label><label>Номер кабинета<input v-model="form.number" required maxlength="20" /></label><label>Этаж<input v-model.number="form.floor" type="number" min="-5" max="150" required /></label><label>Вместимость<input v-model.number="form.capacity" type="number" min="1" max="10000" required /></label><label>Зона доступа<select v-model="form.zone"><option>Общая зона</option><option>Служебная зона</option><option>Ограниченный доступ</option></select></label><label class="span-2">Назначение<textarea v-model="form.purpose" maxlength="300" rows="2"></textarea></label><label class="span-2">Оборудование<textarea v-model="form.equipment" maxlength="500" rows="2" placeholder="Считыватель, электронный замок…"></textarea></label><div v-if="error" class="alert-box span-2" role="alert">{{ error }}</div></form><template #footer><button class="button" :disabled="saving" @click="editing = false">Отмена</button><button class="button primary" type="submit" form="room-form" :disabled="saving">{{ saving ? 'Сохраняем…' : 'Сохранить' }}</button></template></Modal></template>
